// Reused by Project Map and minimal surfaces. No artifact messages become commands.
export function artifactView(value,{ref,onDetach,onIntegrate,refresh}={}){
 const root=document.createElement('section');root.className='artifact-view';const bar=document.createElement('div');bar.className='artifact-toolbar';const viewport=document.createElement('div');viewport.className='artifact-viewport';const content=document.createElement('div');content.className='artifact-content';viewport.append(content);let zoom=1,frame,paused=false,disposed=false,version=0,opened=Date.now(),needsRefresh=false;
 function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;bar.append(b);return b}
 function apply(){content.style.transform=`scale(${zoom})`;content.style.transformOrigin='top left';content.style.width=(100/Math.min(zoom,1))+'%';bar.dataset.zoom=zoom}
 button('−',()=>{zoom=Math.max(.5,zoom-.2);apply()}).setAttribute('aria-label','Reducir vista');button('+',()=>{zoom=Math.min(3,zoom+.2);apply()}).setAttribute('aria-label','Acercar vista');button('Ajustar',()=>{zoom=1;apply();viewport.scrollTo(0,0)});
 if(onDetach)button('Separar / otra pantalla',()=>onDetach(ref));if(onIntegrate)button('Volver al workspace',onIntegrate);
 const pan=button('Desplazar',()=>{const active=pan.getAttribute('aria-pressed')!=='true';pan.setAttribute('aria-pressed',String(active));viewport.classList.toggle('artifact-pan',active)});pan.setAttribute('aria-pressed','false');viewport.addEventListener('pointerdown',e=>{if(pan.getAttribute('aria-pressed')!=='true'||e.button!==0)return;e.preventDefault();const start={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.onpointermove=v=>{viewport.scrollLeft=start.left+start.x-v.clientX;viewport.scrollTop=start.top+start.y-v.clientY};viewport.onpointerup=viewport.onpointercancel=()=>{viewport.onpointermove=null}});
 const notice=document.createElement('p');notice.className='artifact-notice';notice.textContent=value.notice||'Archivo persistente · abrir no lo ejecuta';
 const mount=async()=>{if(document.hidden||paused||disposed)return;const current=++version;if(refresh&&(needsRefresh||Date.now()-opened>60000)){try{value=await refresh();opened=Date.now();needsRefresh=false}catch(e){notice.textContent='No se pudo recuperar la vista: '+e.message;return}if(current!==version||paused||document.hidden||disposed)return;}if(value.kind==='html'){if(frame?.isConnected)return;frame=document.createElement('iframe');frame.className='project-artifact-frame';frame.title='Vista de '+value.path;frame.sandbox='allow-scripts';frame.referrerPolicy='no-referrer';frame.src=value.preview_url+'?theme=dark';content.replaceChildren(frame)}else if(value.kind==='image'){const img=document.createElement('img');img.className='project-artifact-image';img.alt=value.path;img.src=value.data_url;content.replaceChildren(img)}else{const pre=document.createElement('pre');pre.textContent=value.text||'Vista no disponible';content.replaceChildren(pre)}};
 function visibility(){if(document.hidden||paused){needsRefresh=true;++version;content.replaceChildren();frame=null}else mount()}
 document.addEventListener('visibilitychange',visibility);root.setVisible=visible=>{paused=!visible;visibility()};root.dispose=()=>{disposed=true;++version;document.removeEventListener('visibilitychange',visibility);content.replaceChildren()};root.append(bar,notice,viewport);mount();return root;
}
